#!/usr/bin/env node
/**
 * Droid2iOS Studio - Agent Engine v0.4
 * Aplica sobre v0.3:
 * - sticky fallback por tarefa
 * - circuit breaker
 * - checkpoint da rota
 * - validação automática debounced após lotes write/delete
 */
import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const payload = {"electron/types.ts": "", "electron/services/settings.ts": "", "electron/services/providers.ts": "", "electron/services/agent.ts": "", "src/types.ts": "", "src/components/SettingsModal.tsx": "", "electron/services/validation.ts": ""};

function fail(message) {
  console.error(`[v0.4] ERRO: ${message}`);
  process.exit(1);
}

function backup(file, rel) {
  if (!fs.existsSync(file)) return;
  const dst = `${file}.bak-v0.4`;
  if (!fs.existsSync(dst)) {
    fs.copyFileSync(file, dst);
    console.log(`[v0.4] backup: ${rel}.bak-v0.4`);
  }
}

const required = [
  "electron/main.ts",
  "electron/services/workspace.ts",
  "electron/services/settings.ts",
  "electron/services/providers.ts",
  "electron/services/agent.ts",
  "electron/types.ts",
  "src/types.ts",
  "src/components/SettingsModal.tsx"
];

for (const rel of required) {
  if (!fs.existsSync(path.join(root, rel))) {
    fail(`Arquivo obrigatório não encontrado: ${rel}. Rode na raiz do droidios2.`);
  }
}

for (const [rel, encoded] of Object.entries(payload)) {
  const file = path.join(root, rel);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  backup(file, rel);
  fs.writeFileSync(file, Buffer.from(encoded, "base64").toString("utf8"), "utf8");
  console.log(`[v0.4] atualizado: ${rel}`);
}

const mainPath = path.join(root, "electron/main.ts");
let main = fs.readFileSync(mainPath, "utf8");
backup(mainPath, "electron/main.ts");

if (!main.includes("from './services/validation'")) {
  const marker = "import * as workspace from './services/workspace';";
  if (!main.includes(marker)) fail("Import de workspace não encontrado em electron/main.ts.");
  main = main.replace(marker, marker + "\nimport { scheduleValidation } from './services/validation';");
}

const handlerPattern = /ipcMain\.handle\('agent:applyAction',[\s\S]*?\n\s*\}\);/;
const handler = `ipcMain.handle('agent:applyAction', async (_e, action: AgentAction) => {
  const settings = loadSettings();

  if (action.type === 'write_file') {
    const result = workspace.writeFile(action.path, action.content);
    if (settings.autoValidateAgentBatches) scheduleValidation();
    return result;
  }

  if (action.type === 'delete_file') {
    const result = workspace.deleteFile(action.path);
    if (settings.autoValidateAgentBatches) scheduleValidation();
    return result;
  }

  if (action.type === 'run_command') {
    return workspace.runCommand(action.command, action.cwd || '.');
  }
});`;

if (handlerPattern.test(main)) {
  main = main.replace(handlerPattern, handler);
} else if (!main.includes("settings.autoValidateAgentBatches")) {
  fail("Handler agent:applyAction não encontrado em electron/main.ts.");
}

fs.writeFileSync(mainPath, main, "utf8");
console.log("[v0.4] atualizado: electron/main.ts");

console.log("");
console.log("===========================================");
console.log(" Droid2iOS Agent Engine v0.4 aplicado");
console.log("===========================================");
console.log("✓ sticky fallback por tarefa");
console.log("✓ circuit breaker após 2 falhas transitórias");
console.log("✓ checkpoint da rota/modelo");
console.log("✓ validação automática por lote");
console.log("✓ relatório de validação entra no próximo contexto do agente");
console.log("");
console.log("Agora execute:");
console.log("  npm run typecheck");
console.log("  npm run build");
console.log("");
console.log("Depois:");
console.log('  git add .');
console.log('  git commit -m "feat: agent sticky fallback e validacao v0.4"');
console.log("  git push origin main");
